"use client"

import { FileText, Link as LinkIcon, Mail, MessageCircle } from "lucide-react"
import type { ComponentType, ReactNode } from "react"

import {
  Drawer,
  DrawerContent,
  DrawerHandle,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer"

interface SharePerson {
  initials: string
  name: string
}

interface ShareApp {
  icon: ComponentType<{ className?: string }>
  label: string
}

const PEOPLE: SharePerson[] = [
  { initials: "RA", name: "Rosa" },
  { initials: "TM", name: "Theo" },
  { initials: "NC", name: "Nadia" },
]

const APPS: ShareApp[] = [
  { icon: MessageCircle, label: "Messages" },
  { icon: Mail, label: "Mail" },
  { icon: FileText, label: "Notes" },
  { icon: LinkIcon, label: "Copy link" },
]

/** Avatar row for recent contacts, an app grid below, both plain buttons. */
function ShareDrawer({ trigger }: { trigger: ReactNode }) {
  return (
    <Drawer>
      <DrawerTrigger asChild>{trigger}</DrawerTrigger>
      <DrawerContent aria-label="Share">
        <DrawerHandle />
        <DrawerTitle>Share</DrawerTitle>
        <div className="flex gap-4 overflow-x-auto px-4 py-4">
          {PEOPLE.map((person) => (
            <button
              type="button"
              key={person.initials}
              className="flex flex-col items-center gap-1.5 text-xs"
            >
              <span className="bg-muted flex h-12 w-12 items-center justify-center rounded-full text-sm font-medium">
                {person.initials}
              </span>
              {person.name}
            </button>
          ))}
        </div>
        <div className="grid grid-cols-4 gap-3 px-4 pb-6">
          {APPS.map((app) => (
            <button
              type="button"
              key={app.label}
              className="flex flex-col items-center gap-1.5 text-xs"
            >
              <span className="bg-muted flex h-12 w-12 items-center justify-center rounded-xl">
                <app.icon className="h-5 w-5" />
              </span>
              {app.label}
            </button>
          ))}
        </div>
      </DrawerContent>
    </Drawer>
  )
}

export { ShareDrawer }
